using System.Numerics;

public static class Stats
{
    public static T Sum<T>(IEnumerable<T> values) where T : INumber<T>
    {
        T total = T.Zero;
        foreach (var v in values) total += v;
        return total;
    }

    public static T Mean<T>(IReadOnlyCollection<T> values) where T : INumber<T>
    {
        if (values.Count == 0) throw new InvalidOperationException("no values");
        return Sum(values) / T.CreateChecked(values.Count);
    }

    public static T Range<T>(IEnumerable<T> values) where T : INumber<T>
    {
        bool any = false;
        T min = T.Zero, max = T.Zero;
        foreach (var v in values)
        {
            if (!any) { min = max = v; any = true; continue; }
            min = T.Min(min, v);
            max = T.Max(max, v);
        }
        return max - min;
    }
}

unitTests:
Test("sum", () =>
{
    CheckEq(Stats.Sum(new[] { 1, 2, 3 }), 6);
    CheckEq(Stats.Sum(new[] { 0.5, 0.25 }), 0.75);
    CheckEq(Stats.Sum(new decimal[0]), 0m);
});

Test("mean", () =>
{
    CheckEq(Stats.Mean(new[] { 1m, 2m, 4m }), 7m / 3m);
    CheckEq(Stats.Mean(new[] { 1, 2, 4 }), 2);
    CheckThrows<InvalidOperationException>(() => Stats.Mean(new double[0]));
});

Test("range", () =>
{
    CheckEq(Stats.Range(new[] { 5, -2, 9, 3 }), 11);
    CheckEq(Stats.Range(new[] { 2.5 }), 0.0);
    CheckEq(Stats.Range(new long[0]), 0L);
});

